/**
 ******************************************************************************
 * @file    fx_pipe.c
 * TEAM CODE (owner: Jack - audio input and SD storage) - written by the BJT2 team, not generated by STM32CubeMX.
 * Authors: written by Brendon (integrator) on 29-30 Oct 2026 for Jack's storage subsystem (best-ui), with an AI coding assistant;
 *          Brendon (integrator) made effect-file jobs resumable, exactly or by a rebuild with a pre-roll (30 Oct 2026, with an AI coding assistant).
 * @brief   The sample counts of one effect file being made (see fx_pipe.h).
 *
 * Pure logic: no RTOS, no HAL, no FatFs (tests: Tests/test_fx_pipe.c).
 ******************************************************************************/
#include "fx_pipe.h"
#include <string.h>

#define FXP_PERCENT_ALL 100U

/* Room stage_out must keep free: one chunk's worst-case output for the
 * reply on its way (if a chunk is out), and one more for the next chunk to
 * send (if any source is left to send). A SEND is only allowed while that
 * room is there, so a reply always fits. */
static uint32_t fxp_room_needed(const fx_pipe_t *p)
{
    uint32_t chunks = 0U;
    if (p->inflight)
    {
        chunks++;
    }
    if (p->src_sent < p->src_total)
    {
        chunks++;
    }
    return chunks * FXP_CHUNK_OUT;
}

static uint32_t fxp_min(uint32_t a, uint32_t b)
{
    return (a < b) ? a : b;
}

static uint32_t fxp_max(uint32_t a, uint32_t b)
{
    return (a > b) ? a : b;
}

void fxp_begin(fx_pipe_t *p, uint32_t src_samples)
{
    if (p == NULL)
    {
        return;
    }
    memset(p, 0, sizeof(*p));
    p->src_total = src_samples;
}

/* TEAM CODE (written by Brendon, 30 Oct 2026): fxp_continue. Nothing is
 * staged or out: the parked job wrote what it had staged, and its input
 * after `at` is read again. */
void fxp_continue(fx_pipe_t *p, uint32_t src_samples, uint32_t at, uint32_t out_written)
{
    if (p == NULL)
    {
        return;
    }
    fxp_begin(p, src_samples);
    p->src_read = at;
    p->src_sent = at;
    p->src_done = at;
    p->out_written = out_written;
    p->keep_from = at;
    p->first_sent = true;               /* FxRenderTask already has this job's effect state */
}

/* TEAM CODE (written by Brendon, 30 Oct 2026): fxp_rebuild. Nothing is
 * staged or out, as for fxp_continue; the reads start at `from`. */
void fxp_rebuild(fx_pipe_t *p, uint32_t src_samples, uint32_t from, uint32_t at, uint32_t out_written)
{
    if (p == NULL)
    {
        return;
    }
    fxp_begin(p, src_samples);
    const uint32_t start = fxp_min(from, at);
    p->src_read = start;
    p->src_sent = start;
    p->src_done = start;
    p->out_written = out_written;
    p->keep_from = at;
    p->restore = (start > 0U);          /* from 0 the effect state at `at` is the one-go state already */
}

bool fxp_reply_kept(const fx_pipe_t *p)
{
    /* Chunks never straddle keep_from (it is a chunk edge), so the chunk out
     * is kept exactly when it ends after keep_from. */
    return (p != NULL) && p->inflight && (p->src_sent > p->keep_from);
}

uint32_t fxp_kept_samples(const fx_pipe_t *p)
{
    return (p != NULL) ? fxp_max(p->src_done, p->keep_from) : 0U;
}

fxp_action_t fxp_next(const fx_pipe_t *p)
{
    if (p == NULL || p->src_total == 0U)
    {
        return FXP_DONE;                                /* nothing to make */
    }
    const bool staged_out = (p->out_staged > 0U);
    if (staged_out && (p->out_staged + fxp_room_needed(p)) > FXP_STAGE_OUT_SAMPLES)
    {
        return FXP_WRITE;                               /* 1. make room first */
    }
    if (p->stage_pos >= p->stage_len && p->src_read < p->src_total)
    {
        return FXP_READ;                                /* 2. stage_in used up */
    }
    if (!p->inflight && p->stage_pos < p->stage_len)
    {
        return FXP_SEND;                                /* 3. a chunk is ready */
    }
    if (p->inflight)
    {
        return FXP_WAIT;                                /* 4. its reply is due */
    }
    if (staged_out)
    {
        return FXP_WRITE;                               /* 5. the final write */
    }
    return FXP_DONE;                                    /* 6. all sent, back and written */
}

uint32_t fxp_read_size(const fx_pipe_t *p)
{
    if (p == NULL || p->src_read >= p->src_total)
    {
        return 0U;
    }
    return fxp_min(FXP_READ_SAMPLES, p->src_total - p->src_read);
}

void fxp_did_read(fx_pipe_t *p, uint32_t n)
{
    if (p == NULL)
    {
        return;
    }
    p->src_read += n;
    p->stage_len = n;
    p->stage_pos = 0U;
}

uint32_t fxp_chunk(const fx_pipe_t *p, uint8_t *flags)
{
    uint8_t f = 0U;
    uint32_t n = 0U;
    if (p != NULL && p->stage_pos < p->stage_len)
    {
        n = fxp_min(FXP_CHUNK_IN, p->stage_len - p->stage_pos);
        if (!p->first_sent)
        {
            f |= FXP_FLAG_FIRST;
        }
        if (p->restore && p->src_sent == p->keep_from)
        {
            f |= FXP_FLAG_RESTORE;      /* the first chunk after a rebuild's pre-roll */
        }
        if (p->src_sent + n >= p->src_total)
        {
            f |= FXP_FLAG_LAST;
        }
    }
    if (flags != NULL)
    {
        *flags = f;
    }
    return n;
}

void fxp_did_send(fx_pipe_t *p, uint32_t n)
{
    if (p == NULL)
    {
        return;
    }
    p->stage_pos += n;
    p->src_sent += n;
    p->inflight = true;
    p->first_sent = true;
}

void fxp_did_reply(fx_pipe_t *p, uint32_t n_out)
{
    if (p == NULL)
    {
        return;
    }
    const bool kept = fxp_reply_kept(p);
    p->inflight = false;
    p->src_done = p->src_sent;          /* one chunk out at most: all that was sent is back */
    if (kept)
    {
        p->out_staged += n_out;         /* a pre-roll chunk's output is not kept */
    }
}

uint32_t fxp_write_size(const fx_pipe_t *p)
{
    if (p == NULL)
    {
        return 0U;
    }
    return fxp_min(p->out_staged, FXP_STAGE_OUT_SAMPLES);
}

void fxp_did_write(fx_pipe_t *p, uint32_t n)
{
    if (p == NULL)
    {
        return;
    }
    p->out_written += n;
    p->out_staged = (n >= p->out_staged) ? 0U : (p->out_staged - n);
}

uint8_t fxp_percent(const fx_pipe_t *p)
{
    if (p == NULL || p->src_total == 0U)
    {
        return FXP_PERCENT_ALL;
    }
    /* 64-bit: src_done x 100 overflows 32 bits above 42 million samples.
     * fxp_kept_samples: during a pre-roll the percentage stays where the job
     * stopped, so the Preparing screen never goes back. */
    const uint64_t percent = ((uint64_t)fxp_kept_samples(p) * FXP_PERCENT_ALL) / p->src_total;
    return (uint8_t)percent;
}
